    out = {}
    for s in prog[1]:
        if s[0] == "input":
            out[s[1]] = (s[2], s[3])
    return out


def ground_truth(prog):
    iv = input_vars(prog)
    names = list(iv.keys())
    ranges = [range(iv[n][0], iv[n][1] + 1) for n in names]
