def total_combos(prog):
    iv = input_vars(prog)
    t = 1
    for lo, hi in iv.values():
        t *= (hi - lo + 1)
    return t


def self_check():
    """用穷举真值复核内置期望判定（大范围程序跳过，已由出题方 fuzz 验证）。"""
