def run_verifier(verify_path, src):
    """跑 `verify.py <程序文件>`，返回 (verdict, counterexample_dict_or_None, raw_stdout, stderr)。"""
    fd, path = tempfile.mkstemp(suffix=".txt", prefix="prog_", dir=HERE)
